			worker.join(TimeUnit.SECONDS.toMillis(WAIT_SECONDS));
			assertFalse(worker.isAlive());
			assertInstanceOf(TimeLimitReached.class, result.get());
			assertEquals(List.of("cancel", "interrupt", "close"), events);
