	@Test
	void timeoutAfterExplicitCloseIsReportedWhileCallIsActive() throws Exception {
		ConcurrentSource source = new ConcurrentSource();
		TimedIteration iteration = new TimedIteration(source, HOUR_MILLIS, HOUR_MILLIS, HOUR_MILLIS);
		try (ExecutorService executor = Executors.newFixedThreadPool(2)) {
			Future<Boolean> call = executor.submit(iteration::hasNext);
			Future<?> close = null;
			try {
				assertTrue(source.callEntered.await(WAIT_SECONDS, TimeUnit.SECONDS));
				close = executor.submit(iteration::close);
				assertTrue(source.cancellationEntered.await(WAIT_SECONDS, TimeUnit.SECONDS));
				// Deliver the timer action while explicit close owns the blocked cancellation request.
				iteration.interrupt();
				source.releaseCall.countDown();
				ExecutionException failure = assertThrows(ExecutionException.class,
						() -> call.get(WAIT_SECONDS, TimeUnit.SECONDS));
				assertInstanceOf(TimeLimitReached.class, failure.getCause());
				assertTrue(source.closed.await(WAIT_SECONDS, TimeUnit.SECONDS));
			} finally {
				source.releaseCall.countDown();
				source.releaseCancellation.countDown();
				if (close != null) {
					close.get(WAIT_SECONDS, TimeUnit.SECONDS);
				}
				iteration.close();
			}
		}
	}

